'use strict';
const envelope=$input.first()?.json||{};
const built=envelope.builtContext&&typeof envelope.builtContext==='object'&&!Array.isArray(envelope.builtContext)?envelope.builtContext:{};
const incoming=envelope.modelResponse&&typeof envelope.modelResponse==='object'&&!Array.isArray(envelope.modelResponse)?envelope.modelResponse:{};
const response=incoming.body&&typeof incoming.body==='object'?incoming.body:incoming;

const job = built.stateJob && typeof built.stateJob === 'object' ? built.stateJob : {};
const context = built.analysisContext && typeof built.analysisContext === 'object' ? built.analysisContext : {};

const asArray = value => Array.isArray(value) ? value : [];
const clean = value => String(value ?? '').normalize('NFKC').trim();
const normalizeEvidence = value => String(value ?? '').normalize('NFKC').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
const truthyFlag = value => value === true || value === 1 || ['1', 'true', 'yes', 'on'].includes(clean(value).toLowerCase());
const hasOwn = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const finite = value => typeof value === 'number' && Number.isFinite(value);
const inRange = (value, min, max) => finite(value) && value >= min && value <= max;
const isUuid = value => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(value));
const isDate = value => {
  const source = clean(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(source)) return false;
  const date = new Date(`${source}T00:00:00.000Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === source;
};
const shiftIsoDate = (value, dayOffset) => {
  if (!isDate(value)) return '';
  const date = new Date(`${clean(value)}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + dayOffset);
  return date.toISOString().slice(0, 10);
};
const answerText = value => {
  if (typeof value === 'string') return normalizeEvidence(value).slice(0, 4000).trim();
  if (!value || typeof value !== 'object' || Array.isArray(value)) return '';
  return normalizeEvidence(
    value.text ?? value.content ?? value.answerText ?? value.answer_text ??
    value.evidenceText ?? value.evidence_text ?? value.message
  ).slice(0, 4000).trim();
};

const spheres = new Set(['health','energy','mood','calm','clarity','motivation','relationships','progress','inspiration','finance']);
const impactBases = new Set(['explicit', 'clarified_inference', 'neutral_assumption']);
const impactScales = new Set([0.1, 0.35, 0.65, 1]);
const polarityModes = new Set(['positive_only', 'negative_only', 'mixed_allowed', 'mixed_required', 'any']);
const clarificationModes = new Set(['none', 'ask_if_missing', 'required_before_apply']);
const financeModes = new Set(['forbidden', 'realized_only']);
const allowedDays = new Set([1, 3, 7, 14]);
const codePattern = /^[a-z][a-z0-9_]{1,63}$/;
const semanticKeyPattern = /^[a-z][a-z0-9_]*(?::[a-z0-9_]+){1,5}$/;

const originalSourceText = normalizeEvidence(job.content);
const contextJson = job.contextJson && typeof job.contextJson === 'object'
  ? job.contextJson
  : (job.context_json && typeof job.context_json === 'object' ? job.context_json : {});
const eventCorrection = contextJson?.message?.eventCorrection && typeof contextJson.message.eventCorrection === 'object'
  ? contextJson.message.eventCorrection
  : null;
const correctionTarget = eventCorrection?.targetEvent && typeof eventCorrection.targetEvent === 'object'
  ? eventCorrection.targetEvent
  : {};
const answerCollections = [
  built.collectedClarificationAnswerSegments,
  job.collectedClarificationAnswerSegments,
  job.collected_clarification_answer_segments,
  job.clarificationAnswerSegments,
  job.clarification_answer_segments,
  contextJson.collectedClarificationAnswerSegments,
  contextJson.collected_clarification_answer_segments,
  context.collectedClarificationAnswerSegments,
  context.collected_clarification_answer_segments,
  context.clarificationAnswerSegments,
  context.clarification_answer_segments
];
const clarificationSession = context.clarificationSession && typeof context.clarificationSession === 'object'
  ? context.clarificationSession
  : (context.clarification_session && typeof context.clarification_session === 'object'
      ? context.clarification_session
      : {});
answerCollections.push(
  clarificationSession.answers,
  clarificationSession.answerSegments,
  clarificationSession.answer_segments
);
for (const clarification of asArray(context.openClarifications || context.open_clarifications)) {
  answerCollections.push(
    clarification?.answerSegments,
    clarification?.answer_segments,
    clarification?.answers,
    clarification?.answerText,
    clarification?.answer_text
  );
}
const clarificationAnswerSegments = [];
const answerSegmentSet = new Set();
for (const collection of answerCollections) {
  for (const value of (Array.isArray(collection) ? collection : [collection])) {
    const segment = answerText(value);
    if (!segment || answerSegmentSet.has(segment)) continue;
    answerSegmentSet.add(segment);
    clarificationAnswerSegments.push(segment);
    if (clarificationAnswerSegments.length >= 20) break;
  }
  if (clarificationAnswerSegments.length >= 20) break;
}
const allEvidenceSources = [originalSourceText, ...clarificationAnswerSegments].filter(Boolean);
const exactEvidence = value => {
  const needle = normalizeEvidence(value);
  return Boolean(needle) && allEvidenceSources.some(source => source.includes(needle));
};
const exactOriginalEvidence = value => {
  const needle = normalizeEvidence(value);
  return Boolean(needle) && Boolean(originalSourceText) && originalSourceText.includes(needle);
};
const exactClarificationEvidence = value => {
  const needle = normalizeEvidence(value);
  return Boolean(needle) && clarificationAnswerSegments.some(source => source.includes(needle));
};
const temporalAnchorLocalDate = clean(job.localDate || job.local_date);
const temporalContext = built.stateAnalysisTemporalContext && typeof built.stateAnalysisTemporalContext === 'object'
  ? built.stateAnalysisTemporalContext
  : {};
const temporalEvidenceContext = value => {
  const needle = normalizeEvidence(value);
  if (!needle) return '';
  for (const source of allEvidenceSources) {
    const index = source.indexOf(needle);
    if (index < 0) continue;
    let start = index;
    let end = index + needle.length;
    while (start > 0 && !/[.!?;,\n]/u.test(source[start - 1])) start--;
    while (end < source.length && !/[.!?;,\n]/u.test(source[end])) end++;
    return source.slice(start, end).normalize('NFKC').replace(/\s+/g, ' ').trim();
  }
  return needle;
};
const hasFuturePlanCue = value => {
  const candidate = clean(value).toLowerCase();
  return Boolean(candidate) && (
    /(?:^|[^\p{L}\p{N}_])(?:послезавтра|завтра)(?:$|[^\p{L}\p{N}_])/iu.test(candidate) ||
    /(?:в будущем|на следующ(?:ей|ую|ем)|через\s+\d+\s+(?:день|дня|дней|недел|месяц))/iu.test(candidate) ||
    /(?:планир|запланир|в планах|собираюсь|намерен|намерена|намерены|предстоит)/iu.test(candidate) ||
    /(?:^|[^\p{L}\p{N}_])буд(?:у|ешь|ет|ем|ете|ут)(?:$|[^\p{L}\p{N}_])/iu.test(candidate) ||
    /(?:tomorrow|day after tomorrow|in the future|next\s+(?:day|week|month|year)|plan(?:ning)?\s+to|going\s+to|intend\s+to|will\s+)/iu.test(candidate)
  );
};
const relativeDayOffset = value => {
  const candidate = clean(value).toLowerCase();
  if (/(?:^|[^\p{L}\p{N}_])позавчера(?:$|[^\p{L}\p{N}_])|day before yesterday/iu.test(candidate)) return -2;
  if (/(?:^|[^\p{L}\p{N}_])вчера(?:$|[^\p{L}\p{N}_])|yesterday/iu.test(candidate)) return -1;
  if (/(?:^|[^\p{L}\p{N}_])сегодня(?:$|[^\p{L}\p{N}_])|today/iu.test(candidate)) return 0;
  return null;
};
const futurePlanRelativeDayOffset = value => {
  const candidate = clean(value).toLowerCase();
  if (/(?:^|[^\p{L}\p{N}_])послезавтра(?:$|[^\p{L}\p{N}_])|day after tomorrow/iu.test(candidate)) return 2;
  if (/(?:^|[^\p{L}\p{N}_])завтра(?:$|[^\p{L}\p{N}_])|tomorrow/iu.test(candidate)) return 1;
  if (/(?:^|[^\p{L}\p{N}_])сегодня(?:$|[^\p{L}\p{N}_])|today/iu.test(candidate)) return 0;
  return null;
};
const monthNumbers = Object.freeze({
  'января': 1, 'февраля': 2, 'марта': 3, 'апреля': 4, 'мая': 5, 'июня': 6,
  'июля': 7, 'августа': 8, 'сентября': 9, 'октября': 10, 'ноября': 11, 'декабря': 12
});
const validDateParts = (year, month, day) => {
  const iso = `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  return isDate(iso) ? iso : '';
};
const explicitDateConstraints = value => {
  const candidate = clean(value).toLowerCase();
  const constraints = [];
  const seen = new Set();
  const add = (year, month, day) => {
    const numericYear = year === null ? null : Number(year);
    const numericMonth = Number(month);
    const numericDay = Number(day);
    if (numericYear !== null && !validDateParts(numericYear, numericMonth, numericDay)) return;
    if (numericYear === null && !validDateParts(2000, numericMonth, numericDay)) return;
    const key = `${numericYear ?? '*'}-${numericMonth}-${numericDay}`;
    if (seen.has(key)) return;
    seen.add(key);
    constraints.push({ year: numericYear, month: numericMonth, day: numericDay });
  };
  for (const match of candidate.matchAll(/(?:^|[^\d])(\d{4})-(\d{2})-(\d{2})(?!\d)/gu)) {
    add(match[1], match[2], match[3]);
  }
  for (const match of candidate.matchAll(/(?:^|[^\d])([0-3]?\d)[./]([01]?\d)[./](\d{4})(?!\d)/gu)) {
    add(match[3], match[2], match[1]);
  }
  for (const match of candidate.matchAll(/(?:^|[^\d])([0-3]?\d)\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)(?:\s+(\d{4}))?(?!\d)/giu)) {
    add(match[3] || null, monthNumbers[match[2]], match[1]);
  }
  return constraints;
};
const temporalErrors = (prefix, occurredOn, startsOn, evidenceText, implicitDefaultDate = temporalAnchorLocalDate) => {
  const found = [];
  const occurred = clean(occurredOn);
  const starts = clean(startsOn);
  if (!isDate(temporalAnchorLocalDate)) {
    found.push(`${prefix}_temporal_anchor_invalid`);
    return found;
  }
  if (isDate(occurred) && occurred > temporalAnchorLocalDate) found.push(`${prefix}_date_in_future`);
  if (isDate(starts) && starts > temporalAnchorLocalDate) found.push(`${prefix}_starts_in_future`);
  if (isDate(occurred) && isDate(starts) && occurred !== starts) found.push(`${prefix}_starts_on_mismatch`);

  const contextText = temporalEvidenceContext(evidenceText);
  if (hasFuturePlanCue(contextText)) found.push(`${prefix}_future_plan_evidence`);
  const offset = relativeDayOffset(contextText);
  if (offset !== null && isDate(occurred) && occurred !== shiftIsoDate(temporalAnchorLocalDate, offset)) {
    found.push(`${prefix}_relative_date_mismatch`);
  }
  const constraints = explicitDateConstraints(contextText);
  if (constraints.length > 1) found.push(`${prefix}_multiple_explicit_dates`);
  if (constraints.length === 1 && isDate(occurred)) {
    const constraint = constraints[0];
    const parts = occurred.split('-').map(Number);
    if ((constraint.year !== null && parts[0] !== constraint.year) ||
        parts[1] !== constraint.month || parts[2] !== constraint.day) {
      found.push(`${prefix}_explicit_date_mismatch`);
    }
  }
  if (offset === null && constraints.length === 0 && isDate(occurred) && occurred !== implicitDefaultDate) {
    found.push(`${prefix}_implicit_date_mismatch`);
  }
  return found;
};
const hasPersistenceCue = value => {
  const candidate = clean(value).toLowerCase();
  return Boolean(candidate) && (
    /(?:\b(?:1|3|7|14)\s*(?:день|дня|дней|сутки|суток)\b)/iu.test(candidate) ||
    /(?:\b(?:один|три|семь|четырнадцать)\s+(?:день|дня|дней|сутки|суток)\b)/iu.test(candidate) ||
    /(?:уже|в течение|последн|несколько|пару|недел|месяц|до сих пор|всё ещё|все еще|постоян|регуляр|кажд(?:ый|ую|ое)|давно|долго|хронич|не проходит|продолжается)/iu.test(candidate) ||
    /(?:for|during|over|since|still|ongoing|regular|daily|weekly|month|week|days?)/iu.test(candidate)
  );
};

const rawAnalysisMode = clean(
  built.stateAnalysisMode ?? job.analysisMode ?? job.analysis_mode ??
  contextJson.analysisMode ?? contextJson.analysis_mode
).toLowerCase();
const forceNeutralWithoutClarification = [
  job.forceNeutralWithoutClarification,
  job.force_neutral_without_clarification,
  contextJson.forceNeutralWithoutClarification,
  contextJson.force_neutral_without_clarification
].some(truthyFlag);
const expectedAnalysisMode = forceNeutralWithoutClarification || rawAnalysisMode === 'neutral_without_clarification'
  ? 'neutral_without_clarification'
  : 'standard';

const outputTexts = [];
for (const output of asArray(response.output)) {
  for (const content of asArray(output?.content)) {
    if (content?.type === 'output_text' && typeof content.text === 'string') outputTexts.push(content.text);
  }
}
if (!outputTexts.length && typeof response.output_text === 'string') outputTexts.push(response.output_text);
const raw = outputTexts.join('');
let parsed = null;
try { parsed = JSON.parse(raw); } catch {}

const errors = [];
if (!isDate(temporalAnchorLocalDate) ||
    (clean(temporalContext.anchorLocalDate) && clean(temporalContext.anchorLocalDate) !== temporalAnchorLocalDate) ||
    (clean(temporalContext.latestMutableDate) && clean(temporalContext.latestMutableDate) !== temporalAnchorLocalDate)) {
  errors.push('temporal_context_invalid');
}
if (String(response.status || '') !== 'completed') {
  errors.push(`response_not_completed:${clean(response.incomplete_details?.reason || response.status || 'missing_status')}`);
}
if (response.incomplete_details?.reason) {
  errors.push(`response_incomplete:${clean(response.incomplete_details?.reason || response.status)}`);
}
if (outputTexts.length !== 1) errors.push(`response_output_text_count:${outputTexts.length}`);
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) errors.push('response_json_invalid');

const validateShape = (value, allowedKeys, errorPrefix) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return;
  const allowed = new Set(allowedKeys);
  for (const key of allowedKeys) {
    if (!hasOwn(value, key)) errors.push(`${errorPrefix}_field_missing:${key}`);
  }
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) errors.push(`${errorPrefix}_field_unexpected:${key}`);
  }
};

const ruleCatalog = built.stateAnalysisRuleCatalog && typeof built.stateAnalysisRuleCatalog === 'object'
  ? built.stateAnalysisRuleCatalog
  : {};
validateShape(ruleCatalog, [
  'contractVersion','ruleSetCode','ruleSetVersion','ruleCatalogVersion','sphereDefaults','rules'
], 'rule_catalog');
const ruleCatalogContractVersion = clean(ruleCatalog.contractVersion);
const ruleSetCode = clean(ruleCatalog.ruleSetCode);
const ruleSetVersion = ruleCatalog.ruleSetVersion;
const ruleCatalogVersion = ruleCatalog.ruleCatalogVersion;
const ruleMap = new Map();
const catalogEventClasses = new Set();
const sphereDefaultDays = new Map();
if (ruleCatalogContractVersion !== 'chelsea_state_rule_catalog_v1') errors.push('rule_catalog_contract_version_invalid');
if (!codePattern.test(ruleSetCode)) errors.push('rule_catalog_set_code_invalid');
