if (!Number.isSafeInteger(ruleCatalogVersion) || ruleCatalogVersion < 1) {
  errors.push('rule_catalog_version_invalid');
}
for (const [defaultIndex, sphereDefault] of asArray(ruleCatalog.sphereDefaults).entries()) {
  validateShape(sphereDefault, ['sphereCode','durationDays'], `rule_catalog_sphere_default_${defaultIndex}`);
  if (!spheres.has(sphereDefault?.sphereCode) || !allowedDays.has(sphereDefault?.durationDays) ||
    sphereDefaultDays.has(sphereDefault?.sphereCode)) {
    errors.push(`rule_catalog_sphere_default_${defaultIndex}_invalid`);
  } else {
    sphereDefaultDays.set(sphereDefault.sphereCode, sphereDefault.durationDays);
  }
}
if (sphereDefaultDays.size !== spheres.size) errors.push('rule_catalog_sphere_defaults_incomplete');
for (const [ruleIndex, rule] of asArray(ruleCatalog.rules).entries()) {
  const prefix = `rule_catalog_${ruleIndex}`;
  if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
    errors.push(`${prefix}_invalid`);
