    'allowedImpactScales','neutralScale','maxEffects','clarificationPolicy','financePolicy'
  ], prefix);
  const ruleCode = clean(rule.ruleCode);
  if (!codePattern.test(ruleCode) || rule.active !== true || ruleMap.has(ruleCode)) errors.push(`${prefix}_identity_invalid`);
  if (!Array.isArray(rule.eventClasses) || !rule.eventClasses.length ||
    rule.eventClasses.some(value => !codePattern.test(clean(value))) ||
    new Set(rule.eventClasses).size !== rule.eventClasses.length) {
