  }
  for (const eventClass of asArray(rule.eventClasses)) {
    if (codePattern.test(clean(eventClass))) catalogEventClasses.add(eventClass);
  }
  if (!polarityModes.has(rule.polarityMode)) errors.push(`${prefix}_polarity_invalid`);
  if (!Array.isArray(rule.allowedImpactScales) || !rule.allowedImpactScales.length ||
    rule.allowedImpactScales.some(value => !finite(value) || !impactScales.has(value))) {
    errors.push(`${prefix}_impact_scales_invalid`);
  }
  if (!impactScales.has(rule.neutralScale) || !asArray(rule.allowedImpactScales).includes(rule.neutralScale)) {
