  if (!Number.isInteger(rule.maxEffects) || rule.maxEffects < 1 || rule.maxEffects > 4) errors.push(`${prefix}_max_effects_invalid`);
  if (!Array.isArray(rule.allowedEffects) || !rule.allowedEffects.length) errors.push(`${prefix}_allowed_effects_invalid`);
  if (!Array.isArray(rule.requiredEffectGroups)) errors.push(`${prefix}_required_groups_invalid`);
  const allowedEffectPairs = [];
  const allowedEffectCodes = new Set();
  const allowedEffectMap = new Map();
  for (const [allowedIndex, allowed] of asArray(rule.allowedEffects).entries()) {
    validateShape(allowed, [
