      !Number.isInteger(allowed?.minStrength) || !Number.isInteger(allowed?.defaultStrength) ||
      !Number.isInteger(allowed?.maxStrength) ||
      allowed.minStrength < 1 || allowed.maxStrength > 3 ||
      allowed.defaultStrength < allowed.minStrength || allowed.defaultStrength > allowed.maxStrength ||
      !finite(allowed?.minConfidence) || !finite(allowed?.defaultConfidence) || !finite(allowed?.maxConfidence) ||
      allowed.minConfidence < 0.60 || allowed.maxConfidence > 1 ||
      allowed.defaultConfidence < allowed.minConfidence || allowed.defaultConfidence > allowed.maxConfidence ||
      !finite(allowed?.baseWeight) || allowed.baseWeight < 0.5 || allowed.baseWeight > 1.5 ||
