        !asArray(group?.directions).includes(permission.direction))) {
        errors.push(`${prefix}_group_${groupIndex}_permission_metadata_mismatch`);
      }
    }
    if (Number.isInteger(group?.maxCount) && group.maxCount > asArray(group?.effectRuleCodes).length) {
      errors.push(`${prefix}_group_${groupIndex}_impossible`);
    }
  }
