  if (!clarificationPolicy || typeof clarificationPolicy !== 'object' || Array.isArray(clarificationPolicy)) {
    errors.push(`${prefix}_clarification_invalid`);
  } else {
    validateShape(clarificationPolicy, ['mode','requiredSlots','questions'], `${prefix}_clarification`);
    if (!clarificationModes.has(clarificationPolicy.mode)) errors.push(`${prefix}_clarification_mode_invalid`);
    if (!Array.isArray(clarificationPolicy.requiredSlots) || !Array.isArray(clarificationPolicy.questions)) {
      errors.push(`${prefix}_clarification_arrays_invalid`);
    }
    const slotCodes = new Set();
    for (const [slotIndex, slot] of asArray(clarificationPolicy.requiredSlots).entries()) {
      validateShape(slot, ['slotCode','label'], `${prefix}_slot_${slotIndex}`);
      if (!codePattern.test(clean(slot?.slotCode)) || !clean(slot?.label) || slotCodes.has(slot.slotCode)) {
        errors.push(`${prefix}_slot_${slotIndex}_invalid`);
      }
      slotCodes.add(slot?.slotCode);
    }
    const questionCodes = new Set();
    for (const [questionIndex, question] of asArray(clarificationPolicy.questions).entries()) {
      validateShape(question, ['questionCode','slotCodes','questionText','options'], `${prefix}_question_${questionIndex}`);
      if (!codePattern.test(clean(question?.questionCode)) || !clean(question?.questionText) ||
        !Array.isArray(question?.slotCodes) || !question.slotCodes.length ||
        question.slotCodes.some(value => !slotCodes.has(value)) ||
        !Array.isArray(question?.options) || !question.options.length) {
        errors.push(`${prefix}_question_${questionIndex}_invalid`);
      }
      if (questionCodes.has(question?.questionCode)) errors.push(`${prefix}_question_${questionIndex}_duplicate`);
      questionCodes.add(question?.questionCode);
      const optionCodes = new Set();
      for (const [optionIndex, option] of asArray(question?.options).entries()) {
        validateShape(option, ['optionCode','label'], `${prefix}_question_${questionIndex}_option_${optionIndex}`);
        if (!codePattern.test(clean(option?.optionCode)) || !clean(option?.label)) {
          errors.push(`${prefix}_question_${questionIndex}_option_${optionIndex}_invalid`);
        }
        if (optionCodes.has(option?.optionCode)) errors.push(`${prefix}_question_${questionIndex}_option_${optionIndex}_duplicate`);
        optionCodes.add(option?.optionCode);
      }
    }
    if (clarificationPolicy.mode !== 'none' && (!slotCodes.size || !questionCodes.size)) {
      errors.push(`${prefix}_clarification_required_data_empty`);
