    if (clarificationPolicy.mode === 'none' && (slotCodes.size || questionCodes.size)) {
      errors.push(`${prefix}_clarification_none_has_data`);
    }
  }
  const financePolicy = rule.financePolicy;
  if (!financePolicy || typeof financePolicy !== 'object' || Array.isArray(financePolicy)) {
    errors.push(`${prefix}_finance_invalid`);
  } else {
    validateShape(financePolicy, ['mode','evidenceRequired','realizedEvidenceRequired','outcomes'], `${prefix}_finance`);
    if (!financeModes.has(financePolicy.mode) || typeof financePolicy.evidenceRequired !== 'boolean' ||
      typeof financePolicy.realizedEvidenceRequired !== 'boolean') {
