    }
    if (!Array.isArray(financePolicy.outcomes)) errors.push(`${prefix}_finance_outcomes_invalid`);
    if (financePolicy.realizedEvidenceRequired && !financePolicy.evidenceRequired) {
      errors.push(`${prefix}_finance_evidence_policy_invalid`);
    }
    const outcomeDirectionPairs = new Set();
    for (const [outcomeIndex, outcome] of asArray(financePolicy.outcomes).entries()) {
      validateShape(outcome, ['outcomeType','directions','evidencePatterns'], `${prefix}_finance_outcome_${outcomeIndex}`);
      if (!codePattern.test(clean(outcome?.outcomeType)) || !Array.isArray(outcome?.directions) ||
        !outcome.directions.length || outcome.directions.some(value => ![-1, 1].includes(value)) ||
        !Array.isArray(outcome?.evidencePatterns) ||
        (financePolicy.realizedEvidenceRequired && !outcome.evidencePatterns.length)) {
        errors.push(`${prefix}_finance_outcome_${outcomeIndex}_invalid`);
      }
      for (const direction of asArray(outcome?.directions)) {
