  }
  ruleMap.set(ruleCode, rule);
}
if (!ruleMap.size) errors.push('rule_catalog_active_rules_missing');

const result = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
validateShape(result, [
