const dailySignals = [];
for (const collection of [
  context.recentDailySignals,
  context.recent_daily_signals,
  context.dailySignals,
  context.daily_signals,
  context.recentDailyEvents,
  context.recent_daily_events
]) {
  for (const signal of asArray(collection)) {
    const dailySemanticKey = clean(signal.dailySemanticKey || signal.daily_semantic_key);
    if (!dailySemanticKey) continue;
    dailySignals.push({
      dailySemanticKey,
      localDate: clean(signal.localDate || signal.local_date || signal.occurredOn || signal.occurred_on || signal.startsOn || signal.starts_on),
      eventId: clean(signal.eventId || signal.event_id || signal.id)
    });
  }
}
const semanticTokens = value => clean(value).split(/[:_]+/).filter(Boolean);
const nearSemanticKey = (left, right) => {
  const leftTokens = semanticTokens(left);
  const rightTokens = semanticTokens(right);
  if (leftTokens[0] !== rightTokens[0]) return false;
  const a = new Set(leftTokens.slice(1));
  const b = new Set(rightTokens.slice(1));
  if (!a.size || !b.size) return false;
  let intersection = 0;
  for (const token of a) if (b.has(token)) intersection++;
  const smaller = Math.min(a.size, b.size);
  const larger = Math.max(a.size, b.size);
  if (smaller >= 2 && intersection === smaller && larger <= smaller + 1) return true;
  return intersection / (a.size + b.size - intersection) >= 0.75;
};

const financeEvidenceMatches = (outcomeRule, evidence) => {
  const candidate = clean(evidence);
  if (!candidate) return false;
  for (const pattern of asArray(outcomeRule?.evidencePatterns)) {
    try {
      if (new RegExp(pattern, 'iu').test(candidate)) return true;
    } catch {}
  }
  return false;
};

const eventKeys = [
  'clientRef','eventTypeCode','eventClass','ruleCode','ruleSetVersion','dailySemanticKey',
  'summary','evidenceText','temporalEvidenceText','occurredOn','startsOn','confidence',
  'supersedesEventId','expectedSupersededVersion','effects'
];
const effectKeys = [
  'effectRuleCode','sphereCode','direction','strength','confidence','impactBasis','impactScale',
  'financeOutcomeType','financeEvidenceText',
  'durationDays','durationBasis','durationEvidence','impactReason','durationReason',
  'evidencePoints','supersedesEffectId','expectedSupersededVersion','supersedeReason'
];

const validateEvents = (eventsValue, prefix, analysisMode) => {
  const events = asArray(eventsValue);
  if (!Array.isArray(eventsValue)) errors.push(`${prefix}_not_array`);
  if (events.length > 8) errors.push(`${prefix}_count_invalid`);
  const clientRefs = new Set();
  const responseSemanticKeys = [];
  for (const [eventIndex, event] of events.entries()) {
    const eventPrefix = `${prefix}_${eventIndex}`;
    if (!event || typeof event !== 'object' || Array.isArray(event)) {
      errors.push(`${eventPrefix}_invalid`);
      continue;
    }
    validateShape(event, eventKeys, eventPrefix);
    const clientRef = clean(event.clientRef);
    if (!clientRef || clientRefs.has(clientRef)) errors.push(`${eventPrefix}_client_ref_invalid`);
    clientRefs.add(clientRef);
    if (!codePattern.test(clean(event.eventTypeCode))) errors.push(`${eventPrefix}_type_invalid`);
    if (!codePattern.test(clean(event.eventClass))) errors.push(`${eventPrefix}_class_invalid`);
    if (!catalogEventClasses.has(clean(event.eventClass))) errors.push(`${eventPrefix}_class_unknown`);
    const rule = ruleMap.get(clean(event.ruleCode));
    if (!rule) errors.push(`${eventPrefix}_rule_unknown`);
    if (event.ruleSetVersion !== ruleSetVersion) errors.push(`${eventPrefix}_rule_set_version_invalid`);
    if (rule && !rule.eventClasses.includes(clean(event.eventClass))) errors.push(`${eventPrefix}_rule_event_class_mismatch`);

    const dailySemanticKey = clean(event.dailySemanticKey);
    if (!semanticKeyPattern.test(dailySemanticKey) || dailySemanticKey.length > 160) {
      errors.push(`${eventPrefix}_daily_semantic_key_invalid`);
    }
    for (const prior of responseSemanticKeys) {
      if (prior === dailySemanticKey) errors.push(`${eventPrefix}_daily_semantic_duplicate`);
      else if (nearSemanticKey(prior, dailySemanticKey)) errors.push(`${eventPrefix}_daily_semantic_near_duplicate`);
    }
    responseSemanticKeys.push(dailySemanticKey);

    if (!clean(event.summary) || clean(event.summary).length > 600) errors.push(`${eventPrefix}_summary_invalid`);
    if (!exactEvidence(event.evidenceText)) errors.push(`${eventPrefix}_evidence_not_literal`);
    if (!exactEvidence(event.temporalEvidenceText)) errors.push(`${eventPrefix}_temporal_evidence_not_literal`);
    if (!isDate(event.occurredOn) || !isDate(event.startsOn)) errors.push(`${eventPrefix}_date_invalid`);
    const correctionDefaultDate = eventCorrection && eventIndex === 0
      ? clean(eventCorrection.targetOccurredOn || correctionTarget.occurredOn || correctionTarget.occurred_on)
      : temporalAnchorLocalDate;
    errors.push(...temporalErrors(
      eventPrefix,
      event.occurredOn,
      event.startsOn,
      event.temporalEvidenceText,
      isDate(correctionDefaultDate) ? correctionDefaultDate : temporalAnchorLocalDate
    ));
    if (!inRange(event.confidence, 0.60, 1)) errors.push(`${eventPrefix}_confidence_below_apply_threshold`);
    if (event.supersedesEventId === null) {
      if (event.expectedSupersededVersion !== null) errors.push(`${eventPrefix}_empty_supersede_version_invalid`);
    } else {
      const id = clean(event.supersedesEventId);
      const target = activeEvents.get(id);
      if (!isUuid(id) || !target || target.status !== 'active') errors.push(`${eventPrefix}_supersedes_event_unknown`);
      if (!Number.isSafeInteger(event.expectedSupersededVersion) || event.expectedSupersededVersion !== target?.version) {
        errors.push(`${eventPrefix}_supersedes_event_version_invalid`);
      }
    }

    const eventLocalDate = clean(event.occurredOn || job.localDate || job.local_date);
    for (const signal of dailySignals) {
      if (signal.localDate && eventLocalDate && signal.localDate !== eventLocalDate) continue;
      if (event.supersedesEventId !== null && clean(event.supersedesEventId) === signal.eventId) continue;
      if (signal.dailySemanticKey === dailySemanticKey) errors.push(`${eventPrefix}_daily_semantic_duplicate`);
      else if (nearSemanticKey(signal.dailySemanticKey, dailySemanticKey)) errors.push(`${eventPrefix}_daily_semantic_near_duplicate`);
    }

    const effects = asArray(event.effects);
    const maxEffects = rule?.maxEffects || 4;
    if (!Array.isArray(event.effects) || !effects.length || effects.length > maxEffects) errors.push(`${eventPrefix}_effects_count_invalid`);
    const eventSpheres = new Set();
    let positiveCount = 0;
    let negativeCount = 0;
    for (const [effectIndex, effect] of effects.entries()) {
      const effectPrefix = `${eventPrefix}_effect_${effectIndex}`;
      if (!effect || typeof effect !== 'object' || Array.isArray(effect)) {
        errors.push(`${effectPrefix}_invalid`);
        continue;
      }
      validateShape(effect, effectKeys, effectPrefix);
      const effectRuleCode = clean(effect.effectRuleCode);
      if (!codePattern.test(effectRuleCode)) errors.push(`${effectPrefix}_rule_code_invalid`);
      const sphereCode = clean(effect.sphereCode);
      if (!spheres.has(sphereCode)) errors.push(`${effectPrefix}_sphere_invalid`);
      if (eventSpheres.has(sphereCode)) errors.push(`${effectPrefix}_sphere_duplicate_in_event`);
      eventSpheres.add(sphereCode);
      if (!Number.isInteger(effect.direction) || ![-1, 1].includes(effect.direction)) errors.push(`${effectPrefix}_direction_invalid`);
      if (effect.direction === 1) positiveCount++;
      if (effect.direction === -1) negativeCount++;
      const allowedEffect = asArray(rule?.allowedEffects).find(allowed =>
        allowed.effectRuleCode === effectRuleCode
      );
      if (rule && !allowedEffect) errors.push(`${effectPrefix}_not_allowed_by_rule`);
      if (allowedEffect && (allowedEffect.sphereCode !== sphereCode || allowedEffect.direction !== effect.direction)) {
        errors.push(`${effectPrefix}_permission_identity_mismatch`);
      }
      if (!Number.isInteger(effect.strength) ||
        !allowedEffect ||
        effect.strength < allowedEffect.minStrength ||
        effect.strength > allowedEffect.maxStrength) {
        errors.push(`${effectPrefix}_strength_invalid`);
      }
      if (!finite(effect.confidence) ||
        !allowedEffect ||
        effect.confidence < allowedEffect.minConfidence ||
        effect.confidence > allowedEffect.maxConfidence) {
        errors.push(`${effectPrefix}_confidence_below_apply_threshold`);
      }
      if (!impactBases.has(clean(effect.impactBasis))) errors.push(`${effectPrefix}_impact_basis_invalid`);
      if (allowedEffect && !allowedEffect.allowedImpactBases.includes(effect.impactBasis)) {
        errors.push(`${effectPrefix}_impact_basis_not_allowed_by_permission`);
      }
      if (!finite(effect.impactScale) || !impactScales.has(effect.impactScale)) errors.push(`${effectPrefix}_impact_scale_invalid`);
      if (rule && !rule.allowedImpactScales.includes(effect.impactScale)) errors.push(`${effectPrefix}_impact_scale_not_allowed_by_rule`);
      if (effect.impactBasis === 'explicit' && !exactOriginalEvidence(event.evidenceText)) {
        errors.push(`${effectPrefix}_explicit_basis_without_original_evidence`);
      }
      if (effect.impactBasis === 'clarified_inference' && !exactClarificationEvidence(event.evidenceText)) {
        errors.push(`${effectPrefix}_clarified_basis_without_answer_evidence`);
      }
      if (effect.impactBasis === 'neutral_assumption' && analysisMode !== 'neutral_without_clarification') {
        errors.push(`${effectPrefix}_neutral_assumption_not_allowed`);
      }
      if (allowedEffect?.requiresLiteralEvidence && !exactEvidence(event.evidenceText)) {
        errors.push(`${effectPrefix}_literal_evidence_required_by_permission`);
      }
      if (analysisMode === 'neutral_without_clarification' &&
        (effect.strength !== 1 || effect.confidence !== 0.60 || effect.impactScale !== rule?.neutralScale)) {
        errors.push(`${effectPrefix}_neutral_mode_values_invalid`);
      }

      if (sphereCode === 'finance') {
        const financePolicy = rule?.financePolicy;
        if (!financePolicy || financePolicy.mode !== 'realized_only') errors.push(`${effectPrefix}_finance_forbidden_by_rule`);
        const outcomeRule = asArray(financePolicy?.outcomes).find(outcome =>
          outcome.outcomeType === effect.financeOutcomeType && outcome.directions.includes(effect.direction)
        );
        if (!outcomeRule || !codePattern.test(clean(effect.financeOutcomeType))) errors.push(`${effectPrefix}_finance_outcome_not_allowed`);
        if (financePolicy?.evidenceRequired && !exactEvidence(effect.financeEvidenceText)) {
          errors.push(`${effectPrefix}_finance_evidence_not_literal`);
        }
        if (!financePolicy?.evidenceRequired && effect.financeEvidenceText !== null && !exactEvidence(effect.financeEvidenceText)) {
          errors.push(`${effectPrefix}_finance_optional_evidence_not_literal`);
        }
        if (financePolicy?.realizedEvidenceRequired && (!outcomeRule || !financeEvidenceMatches(outcomeRule, effect.financeEvidenceText))) {
          errors.push(`${effectPrefix}_finance_evidence_not_realized`);
        }
        if (allowedEffect?.requiresRealizedOutcome &&
          (!outcomeRule || !financeEvidenceMatches(outcomeRule, effect.financeEvidenceText))) {
          errors.push(`${effectPrefix}_realized_outcome_required_by_permission`);
        }
      } else if (effect.financeOutcomeType !== null || effect.financeEvidenceText !== null) {
        errors.push(`${effectPrefix}_non_finance_fields_invalid`);
      }

      if (!Number.isInteger(effect.durationDays) || !allowedDays.has(effect.durationDays)) errors.push(`${effectPrefix}_duration_invalid`);
      if (allowedEffect && !allowedEffect.allowedDurationDays.includes(effect.durationDays)) {
        errors.push(`${effectPrefix}_duration_not_allowed_by_permission`);
      }
      const durationBasis = clean(effect.durationBasis);
      if (!['sphere_default', 'explicit_user_duration'].includes(durationBasis)) {
        errors.push(`${effectPrefix}_duration_basis_invalid`);
      } else if (durationBasis === 'sphere_default') {
        if (effect.durationDays !== sphereDefaultDays.get(sphereCode)) errors.push(`${effectPrefix}_duration_default_mismatch`);
        if (effect.durationEvidence !== null) errors.push(`${effectPrefix}_duration_default_evidence_invalid`);
      } else {
        if (!exactEvidence(effect.durationEvidence)) errors.push(`${effectPrefix}_duration_evidence_not_literal`);
        if (!hasPersistenceCue(effect.durationEvidence)) errors.push(`${effectPrefix}_duration_evidence_not_persistent`);
      }
      if (!clean(effect.impactReason) || !clean(effect.durationReason)) errors.push(`${effectPrefix}_reason_missing`);
      if (!inRange(effect.evidencePoints, 0, 10)) errors.push(`${effectPrefix}_evidence_points_invalid`);

      if (effect.supersedesEffectId === null) {
        if (effect.expectedSupersededVersion !== null || effect.supersedeReason !== null) {
          errors.push(`${effectPrefix}_empty_supersede_fields_invalid`);
        }
      } else {
        const id = clean(effect.supersedesEffectId);
        const target = activeEffects.get(id);
        if (!isUuid(id) || !target || target.status !== 'active') errors.push(`${effectPrefix}_supersedes_unknown`);
        if (!Number.isSafeInteger(effect.expectedSupersededVersion) || effect.expectedSupersededVersion !== target?.version) {
          errors.push(`${effectPrefix}_supersedes_version_invalid`);
        }
        if (target && target.sphereCode && target.sphereCode !== sphereCode) errors.push(`${effectPrefix}_supersedes_sphere_mismatch`);
        if (!clean(effect.supersedeReason)) errors.push(`${effectPrefix}_supersede_reason_missing`);
      }
    }

    if (rule?.polarityMode === 'positive_only' && negativeCount) errors.push(`${eventPrefix}_polarity_invalid`);
    if (rule?.polarityMode === 'negative_only' && positiveCount) errors.push(`${eventPrefix}_polarity_invalid`);
    if (rule?.polarityMode === 'mixed_required' && (!positiveCount || !negativeCount)) errors.push(`${eventPrefix}_mixed_effects_required`);
    for (const group of asArray(rule?.requiredEffectGroups)) {
      const count = effects.filter(effect =>
        group.effectRuleCodes.includes(clean(effect?.effectRuleCode))
      ).length;
      if (count < group.minCount) errors.push(`${eventPrefix}_required_group_missing:${group.groupCode}`);
      if (count > group.maxCount) errors.push(`${eventPrefix}_required_group_exceeded:${group.groupCode}`);
    }
  }
};

const validateUserScores = (scoresValue, prefix) => {
  const scores = asArray(scoresValue);
  if (!Array.isArray(scoresValue)) errors.push(`${prefix}_not_array`);
  if (scores.length > 10) errors.push(`${prefix}_count_invalid`);
  for (const [index, score] of scores.entries()) {
    const scorePrefix = `${prefix}_${index}`;
    if (!score || typeof score !== 'object' || Array.isArray(score)) {
      errors.push(`${scorePrefix}_invalid`);
      continue;
    }
    validateShape(score, [
      'sphereCode','score','startsOn','durationDays','evidenceText','temporalEvidenceText',
      'supersedesUserScoreId','expectedSupersededVersion'
    ], scorePrefix);
    if (!spheres.has(clean(score.sphereCode))) errors.push(`${scorePrefix}_sphere_invalid`);
    if (!Number.isInteger(score.score) || !inRange(score.score, 1, 10)) errors.push(`${scorePrefix}_value_invalid`);
    if (!isDate(score.startsOn)) errors.push(`${scorePrefix}_date_invalid`);
    if (!Number.isInteger(score.durationDays) || !allowedDays.has(score.durationDays)) errors.push(`${scorePrefix}_duration_invalid`);
    if (!exactEvidence(score.evidenceText)) errors.push(`${scorePrefix}_evidence_not_literal`);
    if (!exactEvidence(score.temporalEvidenceText)) errors.push(`${scorePrefix}_temporal_evidence_not_literal`);
    errors.push(...temporalErrors(scorePrefix, score.startsOn, score.startsOn, score.temporalEvidenceText));
    if (score.supersedesUserScoreId === null) {
      if (score.expectedSupersededVersion !== null) errors.push(`${scorePrefix}_empty_supersede_version_invalid`);
    } else {
      const id = clean(score.supersedesUserScoreId);
      const target = activeUserScores.get(id);
      if (!isUuid(id) || !target || target.status !== 'active') errors.push(`${scorePrefix}_supersede_unknown`);
      if (!Number.isSafeInteger(score.expectedSupersededVersion) || score.expectedSupersededVersion !== target?.version) {
        errors.push(`${scorePrefix}_supersede_version_invalid`);
      }
      if (target && target.sphereCode && target.sphereCode !== clean(score.sphereCode)) {
        errors.push(`${scorePrefix}_supersede_sphere_mismatch`);
      }
    }
  }
};

const futurePlanKeys = [
  'clientRef','planSemanticKey','summary','evidenceText',
  'temporalEvidenceText','plannedFor','confidence'
];
const validateFuturePlans = (plansValue, prefix) => {
  const plans = asArray(plansValue);
  if (!Array.isArray(plansValue)) errors.push(`${prefix}_not_array`);
  if (plans.length > 8) errors.push(`${prefix}_count_invalid`);
  const clientRefs = new Set();
  const semanticKeys = new Set();
  for (const [index, plan] of plans.entries()) {
    const planPrefix = `${prefix}_${index}`;
    if (!plan || typeof plan !== 'object' || Array.isArray(plan)) {
      errors.push(`${planPrefix}_invalid`);
      continue;
    }
    validateShape(plan, futurePlanKeys, planPrefix);
    const clientRef = clean(plan.clientRef);
    const semanticKey = clean(plan.planSemanticKey);
    const plannedFor = clean(plan.plannedFor);
    if (!clientRef || clientRefs.has(clientRef)) errors.push(`${planPrefix}_client_ref_invalid`);
    clientRefs.add(clientRef);
    if (!semanticKeyPattern.test(semanticKey) || semanticKey.length > 160 || semanticKeys.has(semanticKey)) {
      errors.push(`${planPrefix}_semantic_key_invalid`);
    }
    semanticKeys.add(semanticKey);
    if (!clean(plan.summary) || clean(plan.summary).length > 600) errors.push(`${planPrefix}_summary_invalid`);
    if (!exactEvidence(plan.evidenceText)) errors.push(`${planPrefix}_evidence_not_literal`);
    if (!exactEvidence(plan.temporalEvidenceText)) errors.push(`${planPrefix}_temporal_evidence_not_literal`);
    if (!isDate(plannedFor)) {
      errors.push(`${planPrefix}_date_invalid`);
    } else if (plannedFor < temporalAnchorLocalDate) {
      errors.push(`${planPrefix}_date_in_past`);
    }
    if (!inRange(plan.confidence, 0.60, 1)) errors.push(`${planPrefix}_confidence_invalid`);

    const contextText = temporalEvidenceContext(plan.temporalEvidenceText);
    const offset = futurePlanRelativeDayOffset(contextText);
    if (offset !== null && isDate(plannedFor) && plannedFor !== shiftIsoDate(temporalAnchorLocalDate, offset)) {
      errors.push(`${planPrefix}_relative_date_mismatch`);
    }
    const constraints = explicitDateConstraints(contextText);
    if (constraints.length > 1) errors.push(`${planPrefix}_multiple_explicit_dates`);
    if (constraints.length === 1 && isDate(plannedFor)) {
      const constraint = constraints[0];
      const parts = plannedFor.split('-').map(Number);
      if ((constraint.year !== null && parts[0] !== constraint.year) ||
          parts[1] !== constraint.month || parts[2] !== constraint.day) {
        errors.push(`${planPrefix}_explicit_date_mismatch`);
      }
    }
    if (!hasFuturePlanCue(contextText) && isDate(plannedFor) && plannedFor === temporalAnchorLocalDate) {
      errors.push(`${planPrefix}_plan_evidence_missing`);
    }
  }
};

const validateRetractions = (retractionsValue, prefix) => {
  const retractions = asArray(retractionsValue);
  if (!Array.isArray(retractionsValue)) errors.push(`${prefix}_not_array`);
  if (retractions.length > 8) errors.push(`${prefix}_count_invalid`);
  for (const [index, retraction] of retractions.entries()) {
    const itemPrefix = `${prefix}_${index}`;
    if (!retraction || typeof retraction !== 'object' || Array.isArray(retraction)) {
      errors.push(`${itemPrefix}_invalid`);
      continue;
    }
    validateShape(retraction, ['targetEffectId','expectedVersion','reason'], itemPrefix);
    const id = clean(retraction.targetEffectId);
    const target = activeEffects.get(id);
    if (!isUuid(id) || !target || target.status !== 'active') errors.push(`${itemPrefix}_target_unknown`);
    if (!Number.isSafeInteger(retraction.expectedVersion) || retraction.expectedVersion !== target?.version) {
      errors.push(`${itemPrefix}_version_invalid`);
    }
    if (!clean(retraction.reason)) errors.push(`${itemPrefix}_reason_missing`);
  }
};

const optionArraysEqual = (actual, expected) => {
  if (!Array.isArray(actual) || actual.length !== asArray(expected).length) return false;
  return actual.every((option, index) =>
    option && typeof option === 'object' && !Array.isArray(option) &&
    Object.keys(option).length === 2 &&
    option.optionCode === expected[index].optionCode &&
    option.label === expected[index].label
  );
};

const clarificationKeys = [
  'needed','kind','ruleCode','targetEffectId','expectedTargetVersion',
  'questionCode','questionText','questionOptions','responseWindowDays','missingFields','reason'
];
const validateClarification = (clarification, prefix, container, mode, fallback = false) => {
  if (!clarification || typeof clarification !== 'object' || Array.isArray(clarification) || typeof clarification.needed !== 'boolean') {
    errors.push(`${prefix}_invalid`);
    return;
  }
  validateShape(clarification, clarificationKeys, prefix);
  if (!Array.isArray(clarification.missingFields)) errors.push(`${prefix}_missing_fields_invalid`);
  if (!Array.isArray(clarification.questionOptions)) errors.push(`${prefix}_question_options_invalid`);
  const missingSet = new Set();
  for (const field of asArray(clarification.missingFields)) {
    if (!codePattern.test(clean(field))) errors.push(`${prefix}_missing_field_code_invalid`);
    if (missingSet.has(field)) errors.push(`${prefix}_missing_fields_duplicate`);
    missingSet.add(field);
  }
  for (const [index, option] of asArray(clarification.questionOptions).entries()) {
    validateShape(option, ['optionCode','label'], `${prefix}_option_${index}`);
    if (!codePattern.test(clean(option?.optionCode)) || !clean(option?.label)) errors.push(`${prefix}_option_${index}_invalid`);
  }

  if (clarification.needed === false) {
    if (clarification.kind !== null || clarification.ruleCode !== null ||
      clarification.targetEffectId !== null || clarification.expectedTargetVersion !== null ||
      clarification.questionCode !== null || clarification.questionText !== null ||
      asArray(clarification.questionOptions).length ||
      clarification.responseWindowDays !== null || clarification.reason !== null ||
      asArray(clarification.missingFields).length) {
      errors.push(`${prefix}_null_fields_invalid`);
    }
    return;
  }

  if (fallback) errors.push(`${prefix}_fallback_question_forbidden`);
  if (mode === 'neutral_without_clarification') errors.push(`${prefix}_neutral_mode_question_forbidden`);
  if (!['intake_enrichment', 'effect_resolution'].includes(clarification.kind)) errors.push(`${prefix}_kind_invalid`);
  if (!codePattern.test(clean(clarification.ruleCode))) errors.push(`${prefix}_rule_code_invalid`);
  const rule = ruleMap.get(clean(clarification.ruleCode));
  if (!rule) errors.push(`${prefix}_rule_unknown`);
  if (!codePattern.test(clean(clarification.questionCode))) errors.push(`${prefix}_code_invalid`);
  if (!clean(clarification.questionText) || clean(clarification.questionText).length > 500) errors.push(`${prefix}_text_invalid`);
  if (!Number.isInteger(clarification.responseWindowDays) || !allowedDays.has(clarification.responseWindowDays)) {
    errors.push(`${prefix}_duration_invalid`);
  }
  if (!clean(clarification.reason) || clean(clarification.reason).length > 800) errors.push(`${prefix}_reason_invalid`);
  const question = asArray(rule?.clarificationPolicy?.questions).find(value =>
    value.questionCode === clarification.questionCode
  );
  if (!question) {
    errors.push(`${prefix}_question_not_in_catalog`);
  } else {
    if (clarification.questionText !== question.questionText) errors.push(`${prefix}_question_text_mismatch`);
    if (!optionArraysEqual(clarification.questionOptions, question.options)) errors.push(`${prefix}_question_options_mismatch`);
  }

  if (clarification.kind === 'intake_enrichment') {
    if (rule?.clarificationPolicy?.mode === 'none') errors.push(`${prefix}_intake_not_allowed_by_rule`);
    if (clarification.targetEffectId !== null || clarification.expectedTargetVersion !== null) {
      errors.push(`${prefix}_intake_target_must_be_null`);
    }
    const missingFields = asArray(clarification.missingFields);
    if (!missingFields.length) errors.push(`${prefix}_intake_missing_fields_empty`);
    const requiredSlots = new Set(asArray(rule?.clarificationPolicy?.requiredSlots).map(slot => slot.slotCode));
    for (const field of missingFields) {
      if (!requiredSlots.has(field)) errors.push(`${prefix}_missing_field_not_in_rule`);
    }
    if (question && missingFields.length && !missingFields.some(field => question.slotCodes.includes(field))) {
      errors.push(`${prefix}_question_does_not_cover_any_missing_field`);
    }
    if (asArray(container.events).length || asArray(container.userScores).length || asArray(container.retractions).length) {
      errors.push(`${prefix}_intake_contains_mutations`);
    }
  }

  if (clarification.kind === 'effect_resolution') {
    const id = clean(clarification.targetEffectId);
    const target = activeEffects.get(id);
    if (!isUuid(id) || !target || target.status !== 'active') errors.push(`${prefix}_target_unknown`);
    if (!Number.isSafeInteger(clarification.expectedTargetVersion) || clarification.expectedTargetVersion !== target?.version) {
      errors.push(`${prefix}_version_invalid`);
    }
    if (target?.ruleCode && target.ruleCode !== clarification.ruleCode) errors.push(`${prefix}_target_rule_mismatch`);
    if (target?.ruleSetVersion !== undefined && target?.ruleSetVersion !== null &&
      Number(target.ruleSetVersion) !== ruleSetVersion) {
      errors.push(`${prefix}_target_rule_version_mismatch`);
    }
    if (asArray(clarification.missingFields).length) errors.push(`${prefix}_effect_resolution_missing_fields_not_empty`);
    const targetMutated = asArray(container.retractions).some(value => clean(value?.targetEffectId) === id) ||
      asArray(container.events).some(event => asArray(event?.effects).some(effect => clean(effect?.supersedesEffectId) === id));
    if (targetMutated) errors.push(`${prefix}_target_mutated_in_same_result`);
  }
};

validateEvents(result.events, 'event', result.analysisMode);
validateUserScores(result.userScores, 'score');
validateRetractions(result.retractions, 'retraction');
validateFuturePlans(result.futurePlans, 'future_plan');
validateClarification(result.clarification, 'clarification', result, result.analysisMode, false);

if (result.clarification?.needed === true) {
  const fallback = result.neutralFallback;
  if (!fallback || typeof fallback !== 'object' || Array.isArray(fallback)) {
    errors.push('neutral_fallback_required');
  } else {
    validateShape(fallback, [
      'analysisMode','aboutSelf','analysisConfidence','events','userScores','retractions','futurePlans','clarification'
    ], 'neutral_fallback');
    if (fallback.analysisMode !== 'neutral_without_clarification') errors.push('neutral_fallback_mode_invalid');
    if (typeof fallback.aboutSelf !== 'boolean' || fallback.aboutSelf !== result.aboutSelf) errors.push('neutral_fallback_about_self_invalid');
    if (!inRange(fallback.analysisConfidence, 0, 1)) errors.push('neutral_fallback_confidence_invalid');
    if (!Array.isArray(fallback.events)) errors.push('neutral_fallback_events_invalid');
    if (result.clarification.kind === 'intake_enrichment' && !asArray(fallback.events).length) {
      errors.push('neutral_fallback_events_empty');
    }
    validateEvents(fallback.events, 'neutral_fallback_event', 'neutral_without_clarification');
    validateUserScores(fallback.userScores, 'neutral_fallback_score');
    validateRetractions(fallback.retractions, 'neutral_fallback_retraction');
    validateFuturePlans(fallback.futurePlans, 'neutral_fallback_future_plan');
    if (JSON.stringify(fallback.futurePlans) !== JSON.stringify(result.futurePlans)) {
      errors.push('neutral_fallback_future_plans_mismatch');
    }
    if (asArray(fallback.userScores).length || asArray(fallback.retractions).length) {
      errors.push('neutral_fallback_non_event_mutations_forbidden');
    }
    validateClarification(
      fallback.clarification,
      'neutral_fallback_clarification',
      fallback,
      'neutral_without_clarification',
      true
    );
    if (fallback.clarification?.needed !== false) errors.push('neutral_fallback_clarification_must_be_false');
    if (asArray(fallback.events).some(event =>
      event?.supersedesEventId !== null ||
      asArray(event?.effects).some(effect => effect?.supersedesEffectId !== null)
    )) {
      errors.push('neutral_fallback_supersede_forbidden');
    }
    if (result.clarification.kind === 'intake_enrichment' &&
      !asArray(fallback.events).some(event => clean(event?.ruleCode) === clean(result.clarification.ruleCode))) {
      errors.push('neutral_fallback_intake_rule_missing');
    }
  }
} else if (result.neutralFallback !== null) {
  errors.push('neutral_fallback_must_be_null');
}

if (expectedAnalysisMode === 'neutral_without_clarification' && result.clarification?.needed === true) {
  errors.push('neutral_mode_clarification_forbidden');
}
if (result.aboutSelf === false && (
  asArray(result.events).length || asArray(result.userScores).length ||
  asArray(result.retractions).length || asArray(result.futurePlans).length
)) {
  errors.push('non_self_result_contains_self_data');
}

if (eventCorrection) {
  const targetEventId = clean(eventCorrection.targetEventId || correctionTarget.eventId || correctionTarget.id);
  const expectedTargetVersion = Number(eventCorrection.expectedTargetVersion ?? correctionTarget.version);
  const correctedEvents = asArray(result.events);
  const targetEffects = asArray(eventCorrection.targetActiveEffects || correctionTarget.activeEffects)
    .filter(effect => clean(effect?.status || 'active') === 'active');
  if (result.aboutSelf !== true) errors.push('event_correction_about_self_required');
  if (result.clarification?.needed !== false) errors.push('event_correction_clarification_forbidden');
  if (correctedEvents.length !== 1) errors.push('event_correction_single_event_required');
  if (asArray(result.userScores).length) errors.push('event_correction_scores_forbidden');
  if (asArray(result.futurePlans).length) errors.push('event_correction_future_plans_forbidden');
  const replacement = correctedEvents[0] || {};
  if (clean(replacement.supersedesEventId) !== targetEventId) errors.push('event_correction_target_event_mismatch');
  if (!Number.isSafeInteger(expectedTargetVersion) || replacement.expectedSupersededVersion !== expectedTargetVersion) {
    errors.push('event_correction_target_event_version_mismatch');
  }
  const activeIds = new Set(targetEffects.map(effect => clean(effect.effectId || effect.effect_id || effect.id)).filter(Boolean));
  const mutationCounts = new Map([...activeIds].map(id => [id, 0]));
  for (const retraction of asArray(result.retractions)) {
    const id = clean(retraction?.targetEffectId);
    if (!activeIds.has(id)) errors.push('event_correction_outside_retraction_target');
    else mutationCounts.set(id, (mutationCounts.get(id) || 0) + 1);
  }
  for (const effect of asArray(replacement.effects)) {
    if (effect?.supersedesEffectId === null) continue;
    const id = clean(effect?.supersedesEffectId);
    if (!activeIds.has(id)) errors.push('event_correction_outside_supersede_target');
    else mutationCounts.set(id, (mutationCounts.get(id) || 0) + 1);
  }
  for (const [id, count] of mutationCounts) {
    if (count !== 1) errors.push(`event_correction_target_effect_mutation_count:${id}:${count}`);
  }
}

const uniqueErrors = [...new Set(errors)].slice(0, 100);
const preApplyClarificationNeeded = uniqueErrors.length === 0 && result.clarification?.needed === true;
return [{
  json: {
    ...built,
    stateAnalysisRawText: raw.slice(0, 30000),
    stateAnalysisResult: result,
    stateAnalysisValid: uniqueErrors.length === 0,
    stateAnalysisErrors: uniqueErrors,
    stateAnalysisResponseStatus: clean(response.status),
    stateAnalysisIncompleteReason: clean(response.incomplete_details?.reason),
    stateLiteralEvidenceFallbackCount: literalEvidenceFallbackCount,
    stateAnalysisMode: expectedAnalysisMode,
    stateAnalysisContractVersion: 'chelsea_state_analysis_v2',
    stateAnalysisRuleSetCode: ruleSetCode,
    stateAnalysisRuleSetVersion: ruleSetVersion,
    stateAnalysisRuleCatalogVersion: ruleCatalogVersion,
    stateAnalysisTemporalContext: {
      contractVersion: 'chelsea_state_temporal_context_v1',
      anchorLocalDate: temporalAnchorLocalDate,
      latestMutableDate: temporalAnchorLocalDate,
      completedActionsOnly: true,
      futurePlansMutateState: false,
      futurePlansStoredForConfirmation: true
    },
    stateAnalysisPreApplyClarificationNeeded: preApplyClarificationNeeded,
    stateAnalysisPreApplyClarificationKind: preApplyClarificationNeeded ? result.clarification.kind : null,
    stateAnalysisPreApplyNeutralFallback: preApplyClarificationNeeded ? result.neutralFallback : null,
    stateDurationContractVersion: 'chelsea_state_duration_contract_v1_1',
    stateTemporalContractVersion: 'chelsea_state_temporal_context_v1',
    stateFuturePlanContractVersion: 'chelsea_state_future_plan_v1'
  }
}];
